p='css/template.css'
s=open(p).read()
s=s.replace('''  --accent: #e8c547;           /* the one accent color */''','''  --accent: #ffc83d;           /* the leader's colour: warm amber */
  --bar-other: rgba(150, 170, 214, 0.55);  /* the trailing answers' bars: cool slate */
  --live-dot: #ff4d5e;         /* the small live dot beside the label */''')
s=s.replace('--panel-bg: rgba(12, 14, 18, 0.92);','--panel-bg: rgba(10, 15, 30, 0.93);')
s=s.replace('--text-dim: rgba(255,255,255,0.72);','--text-dim: rgba(255,255,255,0.78);')
s=s.replace('--panel-radius: calc(2px * var(--scale));','--panel-radius: calc(6px * var(--scale));')
s=s.replace('''  left: 120px;                     /* inset from the left edge (safe area) */
