  bottom: 84px;                    /* anchored low: grows upward, stays in the lower half */''')
s=s.replace('''  --stage-width: 590px;''','''  --stage-width: 920px;''')
s=s.replace('''  width: 590px;  /* fallback''','''  width: 920px;  /* fallback''')
s=s.replace('''min(calc(590px * var(--scale)), 1680px);''','''min(calc(920px * var(--scale)), 1680px);''')
d=s.index('/* ── Design ── */'); e=s.index('/* Hidden data sources')
design='''/* ── Design ── */
/* The panel: a deep navy slab with an amber top edge. */
.infographic-box {
  width: calc(920px * var(--scale));
  box-sizing: border-box;
  padding: calc(28px * var(--scale)) calc(34px * var(--scale)) calc(30px * var(--scale));
  background: var(--panel-bg);
  border-radius: var(--panel-radius);
  border-top: calc(4px * var(--scale)) solid var(--accent);
  box-shadow: var(--panel-keyline), var(--panel-shadow);
}

/* Kicker: live dot + the label word. */
.poll-kicker {
  display: flex;
  align-items: center;
  gap: calc(12px * var(--scale));
  margin-bottom: calc(10px * var(--scale));
}
.poll-dot {
  flex-shrink: 0;
  width: calc(12px * var(--scale));
  height: calc(12px * var(--scale));
  border-radius: 50%;
  background: var(--live-dot);
  box-shadow: 0 0 0 calc(4px * var(--scale)) rgba(255, 77, 94, 0.22);
}
.poll-kicker-word {
  font-size: calc(20px * var(--scale) * var(--type-scale));
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: var(--label-tracking);
  text-transform: uppercase;
  color: var(--accent);
}

/* The question: the line the audience reads first. */
.infographic-heading {
  font-size: calc(36px * var(--scale) * var(--type-scale));
  font-weight: 700;
  line-height: 1.18;
  letter-spacing: -0.01em;
  color: var(--text-color);
  overflow-wrap: break-word;
  text-wrap: balance;
}

.infographic-rule {
  height: 1px;
  margin: calc(18px * var(--scale)) 0 calc(14px * var(--scale));
  background: rgba(255, 255, 255, 0.14);
}

/* The answers: one row each - answer, bar, share. */
#infographic-bars {
  display: flex;
  flex-direction: column;
  gap: calc(6px * var(--scale));
}
.infographic-row {
  display: flex;
  align-items: center;
  gap: calc(22px * var(--scale));
  min-height: calc(52px * var(--scale));
  padding: calc(6px * var(--scale)) calc(16px * var(--scale));
  margin: 0 calc(-16px * var(--scale));
  border-radius: calc(4px * var(--scale));
  border-left: calc(4px * var(--scale)) solid transparent;
  transition: background-color 0.4s ease, border-color 0.4s ease;
}
.infographic-bar-label {
  flex: 0 0 calc(260px * var(--scale));
  min-width: 0;
  font-size: calc(26px * var(--scale) * var(--type-scale));
  font-weight: 500;
  line-height: 1.2;
  color: var(--text-dim);
  overflow-wrap: break-word;
  transition: color 0.4s ease;
}
.infographic-bar-track {
  flex: 1 1 auto;
  min-width: 0;
  height: calc(16px * var(--scale));
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
}
.infographic-bar-fill {
  width: 0;
  height: 100%;
  border-radius: inherit;
  background: var(--bar-other);
  transition: background-color 0.4s ease;
  will-change: width;
}
.infographic-bar-value {
  flex: 0 0 calc(112px * var(--scale));
  text-align: right;
  white-space: nowrap;
  font-size: calc(28px * var(--scale) * var(--type-scale));
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  font-family: var(--font-numeric);
  color: var(--text-dim);
  transition: color 0.4s ease;
}

/* The leading answer: amber bar, full-white answer, amber share, a lit row. */
.infographic-row.is-leader {
  background: rgba(255, 200, 61, 0.12);
  border-left-color: var(--accent);
}
.infographic-row.is-leader .infographic-bar-label { color: var(--text-color); font-weight: 700; }
.infographic-row.is-leader .infographic-bar-fill { background: var(--accent); }
.infographic-row.is-leader .infographic-bar-value { color: var(--accent); font-weight: 800; font-size: calc(32px * var(--scale) * var(--type-scale)); }

'''
s=s[:d]+design+s[e:]
open(p,'w').write(s)
